(function(){
'use strict';
const B=window.BuildingExports,button=document.createElement('button');button.id='walkmode';button.textContent='Walk';button.title='Walk through this building';button.setAttribute('aria-pressed','false');document.querySelector('.viewmode').append(button);
const windowButton=document.createElement('button');windowButton.id='tool-window';windowButton.textContent='Window';windowButton.title='Place windows along a wall';$('tool-door').after(windowButton);windowButton.onclick=()=>{if(tool==='door'&&connectionKind==='window'){setTool('select');return;}connectionKind='window';$('newconnectiontype').value='window';setTool('door');};if(!$('newconnectiontype').querySelector('option[value="window"]'))$('newconnectiontype').add(new Option('Window / window series','window'));const oldDoor=$('tool-door').onclick;$('tool-door').onclick=()=>{if(connectionKind==='window'){connectionKind='single';$('newconnectiontype').value='single';}oldDoor();};
const hud=document.createElement('div');hud.id='walkhud';hud.hidden=true;hud.innerHTML='<span>WASD move · mouse look · Ctrl crouch · F flashlight · Esc exit</span><button id="walkreset">Entrance</button><button id="walkflash">Flashlight on</button><button id="walkexit">Exit walk</button>';document.querySelector('.workspace').append(hud);
const locationLabel=document.createElement('span');locationLabel.id='walklocation';hud.prepend(locationLabel);const caps=document.createElement('label');caps.innerHTML='<input id="threeceilings" type="checkbox"> Roofs / inter-floor caps';document.querySelector('.threetoggles').append(caps);$('threeceilings').onchange=e=>B.getViewer()?.setCeilings(e.target.checked);const slabs=document.createElement('label');slabs.innerHTML='<input id="threeslabs" type="checkbox" checked> Floor slabs';document.querySelector('.threetoggles').append(slabs);$('threeslabs').onchange=e=>B.getViewer()?.setSlabs(e.target.checked);
const menu=document.createElement('div');menu.id='explorermenu';menu.className='connectionmenu';menu.hidden=true;document.body.append(menu);
const edit=document.createElement('section');edit.id='room3dedit';edit.hidden=true;$('threeoptions').prepend(edit);
let world=null,walking=false,yaw=0,pitch=0,flash=true,keys=new Set(),last=0,raf=0,look=null,scope=null,lastPoint=null,crouched=false,eyeHeight=1.62;
function stop(){walking=false;if(document.pointerLockElement)document.exitPointerLock?.();keys.clear();cancelAnimationFrame(raf);B.getViewer()?.setWalk(null);hud.hidden=true;button.setAttribute('aria-pressed','false');$('walkavatar')?.remove();document.body.classList.remove('walking');}
function start(point){if(!walking){world=window.KERN_WALK.create(B.currentGeometry());scope=currentBuilding().id;yaw=0;pitch=0;}if(point){const q=world.supported({x:point.x,y:point.y,z:point.z});if(!q){notify('Choose a clear, walkable floor position');return;}world.setState(q);}resetTransient(true);walking=true;button.setAttribute('aria-pressed','true');hud.hidden=false;document.body.classList.add('walking');last=performance.now();cancelAnimationFrame(raf);tick(last);captureMouse();}
function captureMouse(){if(!walking||!B.isThreeMode())return;const canvas=$('threeviewport').querySelector('canvas');if(canvas?.requestPointerLock){try{const p=canvas.requestPointerLock();p?.catch(()=>notify('Click the 3D view to capture the mouse'));}catch{notify('Click the 3D view to capture the mouse');}}}
function avatar(){let g=$('walkavatar');if(!g){g=document.createElementNS('http://www.w3.org/2000/svg','g');g.id='walkavatar';g.setAttribute('pointer-events','none');g.innerHTML='<circle r=".32" fill="#4fa8ff" stroke="white" stroke-width=".08"/><path d="M-.18 -.35 L0 -.75 L.18 -.35" fill="#fff"/>'; $('plan').append(g);}g.setAttribute('transform',`translate(${world.state.x} ${world.state.y}) rotate(${-yaw*180/Math.PI})`);}
function tick(now){if(!walking)return;if(scope!==currentBuilding().id){stop();return;}const dt=Math.min(.05,(now-last)/1000);last=now;const crouchWanted=keys.has('control')||keys.has('c');if(crouchWanted!==crouched&&world.setCrouch(crouchWanted))crouched=crouchWanted;eyeHeight+=( (crouched?1.08:1.62)-eyeHeight)*Math.min(1,dt*12);if(document.querySelector('dialog[open]'))keys.clear();let x=Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft')),y=Number(keys.has('s')||keys.has('arrowdown'))-Number(keys.has('w')||keys.has('arrowup'));const len=Math.hypot(x,y);if(len){const speed=(crouched?1.5:keys.has('shift')?4.2:2.5)*dt/len;x*=speed;y*=speed;world.move(B.isThreeMode()?x*Math.cos(yaw)+y*Math.sin(yaw):x,B.isThreeMode()?-x*Math.sin(yaw)+y*Math.cos(yaw):y);}const here=model.floors[world.state.floor]?.rooms.find(r=>!['void','solid'].includes(r.type)&&world.state.x>=r.x&&world.state.x<=r.x+r.w&&world.state.y>=r.y&&world.state.y<=r.y+r.h&&Math.abs((r.z??model.floors[world.state.floor].z)-world.state.z)<.6);locationLabel.textContent=world.state.floor+' · '+(here?.name||'Outside / stairs');if(B.isThreeMode())B.getViewer()?.setWalk({...world.state,eyeHeight},yaw,pitch,flash);else{if(world.state.floor!==floorId){floorId=world.state.floor;render();}avatar();}raf=requestAnimationFrame(tick);}
function selectRoom(fid,rid){if(walking)return;floorId=fid;selected=rid;selectedDoor=null;document.body.classList.add('editing3d');$('inspector').hidden=false;document.querySelector('.asidehead').hidden=false;inspector();const r=room(rid);if(!r)return;edit.hidden=true;edit.innerHTML=`<h3>${esc(r.name)}</h3><div class="gridfields">${['x','y','w','h'].map(k=>`<label class="field"><span>${({x:'X',y:'Y',w:'Width',h:'Depth'})[k]} · m</span><input data-room3d="${k}" type="number" step="0.5" value="${r[k]}" ${canEdit(r)?'':'disabled'}></label>`).join('')}</div><div class="threebuttons"><button data-copy3d>Copy</button><button data-duplicate3d>Duplicate</button><button data-delete3d>Delete</button></div>`;edit.querySelector('[data-copy3d]').onclick=()=>KERN_OBJECT_UI.clipboard('c');edit.querySelector('[data-duplicate3d]').onclick=()=>{KERN_OBJECT_UI.clipboard('c');KERN_OBJECT_UI.clipboard('v');};edit.querySelector('[data-delete3d]').onclick=()=>deleteSelection();edit.onchange=e=>{const k=e.target.dataset.room3d,v=snap(Number(e.target.value));if(!k||!Number.isFinite(v))return;editRoom(fid,rid,{...footprint(r),[k]:v});};B.getViewer()?.selectRoom?.(fid,rid);}
function editRoom(fid,rid,rect){floorId=fid;const r=room(rid);if(!canEdit(r))return;if(['x','y','w','h'].some(k=>!Number.isFinite(rect[k]))||rect.w<1||rect.h<1||rect.w>150||rect.h>150||Math.abs(rect.x)>150||Math.abs(rect.y)>150)return;commit(()=>{for(const k of ['x','y','w','h'])r[k]=snap(rect[k]);syncStairEdit(r)});edit.hidden=true;}
function showMenu(p){if(walking)return;lastPoint=p;menu.innerHTML=`<button data-action="walk">Walk from here</button>${p.room?'<button data-action="copy">Copy</button><button data-action="duplicate">Duplicate</button>':''}<button data-action="paste">Paste</button>`;menu.hidden=false;menu.style.left=Math.min(p.clientX,innerWidth-210)+'px';menu.style.top=Math.min(p.clientY,innerHeight-170)+'px';}
menu.onclick=e=>{const a=e.target.dataset.action,p=lastPoint;if(!a||!p)return;menu.hidden=true;if(a==='walk'){start(p);return;}floorId=p.floor;if(p.room){selected=p.room;selectedDoor=null;}if(a==='copy')KERN_OBJECT_UI.clipboard('c');if(a==='duplicate'){KERN_OBJECT_UI.clipboard('c');KERN_OBJECT_UI.clipboard('v');}if(a==='paste')KERN_OBJECT_UI.clipboard('v');};
$('plan').addEventListener('contextmenu',e=>{if(walking)return;e.preventDefault();e.stopImmediatePropagation();const p=$('plan').createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform($('plan').getScreenCTM().inverse()),r=room(e.target.closest?.('[data-room]')?.dataset.room)||floor().rooms.find(r=>q.x>=r.x&&q.x<=r.x+r.w&&q.y>=r.y&&q.y<=r.y+r.h);showMenu({x:q.x,y:q.y,z:r?.z??floor().z,floor:floorId,room:r?.id,clientX:e.clientX,clientY:e.clientY});},true);
document.addEventListener('pointerdown',e=>{if(!menu.contains(e.target))menu.hidden=true;if(walking&&e.target.closest('#threeviewport')){captureMouse();look={x:e.clientX,y:e.clientY};e.preventDefault();}},true);
document.addEventListener('pointermove',e=>{if(walking&&document.pointerLockElement){yaw-=e.movementX*.0025;pitch=Math.max(-1.4,Math.min(1.4,pitch-e.movementY*.0025));}else if(look&&walking){yaw-=(e.clientX-look.x)*.0025;pitch=Math.max(-1.4,Math.min(1.4,pitch-(e.clientY-look.y)*.0025));look={x:e.clientX,y:e.clientY};}},true);document.addEventListener('pointerup',()=>look=null,true);
window.addEventListener('keydown',e=>{if(!walking)return;if(isTypingTarget(e.target))return;e.preventDefault();e.stopImmediatePropagation();const k=e.key.toLowerCase();if(k==='escape'){stop();return;}if(k==='f'&&!e.repeat){flash=!flash;$('walkflash').textContent='Flashlight '+(flash?'on':'off');}keys.add(k);},true);window.addEventListener('keyup',e=>{if(walking){keys.delete(e.key.toLowerCase());e.preventDefault();e.stopImmediatePropagation();}},true);document.addEventListener('pointerlockchange',()=>{if(walking&&B.isThreeMode()&&!document.pointerLockElement)stop();});window.addEventListener('blur',()=>{keys.clear();look=null;});
$('plan').addEventListener('pointerdown',e=>{if(walking){e.preventDefault();e.stopImmediatePropagation();}},true);
button.onclick=()=>walking?stop():start();$('walkexit').onclick=stop;$('walkreset').onclick=()=>world?.reset();$('walkflash').onclick=()=>{flash=!flash;$('walkflash').textContent='Flashlight '+(flash?'on':'off');};
window.addEventListener('keydown',e=>{if(walking||!B.isThreeMode()||isTypingTarget(e.target)||document.querySelector('dialog[open]'))return;const k=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&['c','x','v','z','y'].includes(k)){e.preventDefault();e.stopImmediatePropagation();if(e.repeat)return;if(k==='z')e.shiftKey?redo():undo();else if(k==='y')redo();else KERN_OBJECT_UI.clipboard(k);}else if(['Delete','Backspace'].includes(e.key)&&selected){e.preventDefault();deleteSelection();}},true);
window.KERN_EXPLORER={selectRoom,editRoom,menu:showMenu,sync(){const settings=B.getViewer()?.getViewState?.();if(settings){$('threeceilings').checked=!!settings.showCeilings;$('threeslabs').checked=settings.showSlabs!==false;}if(!walking&&document.body.classList.contains('editing3d')&&selected)B.getViewer()?.selectRoom?.(floorId,selected);if(walking&&scope===currentBuilding().id)B.getViewer()?.setWalk({...world.state,eyeHeight},yaw,pitch,flash);},start,stop,get active(){return walking}};
})();
